const upsertColdDay = `-- name: UpsertColdDay :exec
INSERT INTO cold_days (kind, date, body) VALUES (?1, ?2, ?3)
ON CONFLICT(kind, date) DO UPDATE SET body = excluded.body, updated_at = CAST(unixepoch('subsec') * 1000 AS INTEGER)
`

type UpsertColdDayParams struct {
	Kind string
	Date string
	Body []byte
}

// Packaging a day again writes it again, and says when
func (q *Queries) UpsertColdDay(ctx context.Context, arg UpsertColdDayParams) error {
	_, err := q.exec(ctx, q.upsertColdDayStmt, upsertColdDay, arg.Kind, arg.Date, arg.Body)
	return err
}
